examples.setup:
@State private var lines = [
    MonarchLogLine(id: "1", message: "GET /v1/invoices 200"),
    MonarchLogLine(id: "2", message: "GET /v1/invoices 500", level: .error),
]

examples.code:
MonarchLogViewer(
    lines,
    query: .constant("invoices"),
    isWrapped: .constant(true),
    searchMode: .highlight,
    showsLineNumbers: true
) {
    Button("Clear") { lines.removeAll() }
        .buttonStyle(.monarch(.ghost, size: .sm))
}
.frame(height: 300)
